#include<cstdint>
#include<iostream>
#include<vector>
#include<cstdlib>

int64_t nb_digits(int64_t n) {
    n = n < 0 ? -n : n;
    int64_t digits = 0;
    for (; n; n /= 10) ++digits;
    return digits;
}

inline int64_t ones(int64_t n) {
    int64_t res = 0;
    for (int i = 0; i < n; ++i)
        res = 10 * res + 1;
    return res;
}

int64_t aux2(int64_t n) {
    if (n == 0) return 0;
    n = std::abs(n);
    int64_t d = nb_digits(n);
    return d + aux2(n - ones(d));
}

static bool can_add(int64_t current, int64_t sign) {
    // condition: 0 <= current*sign && -10 < current < 10
    // equivalent: (current >= 0 && sign > 0) || (current <= 0 && sign < 0) but also -10 < current < 10.
    // Simplify: abs(current) < 10 and current*sign >= 0.
    return (std::abs(current) < 10) && (current * sign >= 0);
}

int64_t aux(int64_t n, int64_t sign, int64_t acc, int64_t max, std::vector<int> &already_in) {
    if (acc >= max) return max;
    if (n == 0) return acc;
    if (n < 0) { n = -n; sign = -sign; }
    int64_t d = nb_digits(n);
    int64_t ones_d = ones(d);
    int64_t res1 = max, res2 = max;

    // use the new condition
    if (can_add(already_in[d], sign)) {
        already_in[d] += sign;
        res1 = aux(n - ones_d, sign, acc + d, max, already_in);
        already_in[d] -= sign;
    }
    if (can_add(already_in[d+1], sign)) {
        already_in[d+1] += sign;
        res2 = aux(n - 10*ones_d - 1, sign, acc + d + 1, res1, already_in);
        already_in[d+1] -= sign;
    }
    return res1 < res2 ? res1 : res2;
}

int main(int argc, char* argv[]) {
    int64_t n;
    std::cin >> n;
    std::vector<int> already_in(20, 0);
    std::cout << aux(n, 1, 0, aux2(n), already_in) << std::endl;
    return 0;
}
